/* ---------- rapid responder: median first-response time on messages + leads ---------- */
function respCalc(cid){const s=[];const th={};
 DB.msgs.forEach(m=>{if(m.b!==cid)return;(th[m.a]=th[m.a]||[]).push(m)});
 for(const k in th){let wait=null;th[k].slice().sort((x,y)=>x.date-y.date).forEach(m=>{if(m.from!==cid){if(wait===null)wait=m.date}else if(wait!==null){if(!/auto-reply, demo/.test(m.text))s.push(m.date-wait);wait=null}})}
 DB.jobs.forEach(j=>{if((j.invited||[]).includes(cid)){const q=DB.quotes.find(q=>q.job===j.id&&q.cid===cid);if(q)s.push(Math.max(0,q.date-j.created))}});
 (DB.projects||[]).forEach(p=>p.roles.forEach(r=>(r.invites||[]).forEach(i=>{if(i.cid===cid&&i.respAt&&!i.auto)s.push(Math.max(0,i.respAt-i.date))})));
 if(!s.length)return{n:0,med:null};s.sort((a,b)=>a-b);const h=s.length>>1;return{n:s.length,med:s.length%2?s[h]:(s[h-1]+s[h])/2}}
function respStats(cid){const u=U(cid);if(!V2SERVER&&u&&u.rs)return u.rs;return respCalc(cid)}
const isRapid=cid=>{const r=respStats(cid);return r.n>0&&r.med!=null&&r.med<36e5};
