function estimateRange(o){o=o||{};const cat=EST_BASE[o.cat]?o.cat:"Handyman";const [b0,b1]=EST_BASE[cat];const sz=EST_SIZE[o.size]||EST_SIZE.medium,ur=EST_URG[o.urg]||EST_URG.soon;const st=ZIPS[o.zip]?ZIPS[o.zip][0].slice(-2):"";const rg=EST_REGION[st]||1;const d=String(o.desc||"").toLowerCase();
 const f=[{k:"Base range for "+cat,v:money(b0)+"–"+money(b1)},{k:"Size: "+sz[1],x:sz[0]},{k:"Urgency: "+ur[1],x:ur[0]},{k:"Regional cost index"+(st?" ("+st+")":""),x:rg}];
 let m=sz[0]*ur[0]*rg;EST_KW.forEach(([re,x,t])=>{if(re.test(d)){m*=x;f.push({k:"From your description: "+t,x})}});
 const rd=n=>n<1000?Math.round(n/10)*10:Math.round(n/50)*50;return{cat,low:rd(b0*m),high:rd(b1*m),mult:Math.round(m*100)/100,factors:f}}

