/* ---------- PROJECT: crew builder ---------- */
function crewBuilder(p){const win=p.start&&p.end?`${fmtD(p.start)} – ${fmtD(p.end)}`:"Dates not set";const s=slots(p);
 return`<div class="cb" id="crewBuilder"><div class="cb-top"><div><span class="kick">${I("users",14)} Crew builder</span><h2>Build the whole crew for ${esc(win)}</h2><p class="muted">Suggestions match each slot's trade, serve ${esc(townOf(p.zip))}, and are free that whole window. Rapid responders rank first.</p></div><div class="cb-sum"><b>${s.f}<small>/${s.n}</small></b><span>slots filled</span></div></div>
 ${p.roles.map(r=>{const inv=(r.invites||[]).filter(i=>i.status==="invited");const open=Math.max(0,r.need-r.filled.length);const sg=crewSuggest(p,r);const want=Math.max(0,open-inv.length);
  return`<article class="cb-role ${open?"":"full"}" data-rid="${r.id}"><header><div><b>${esc(r.label)}</b><small>${I(TRADE_ICON[r.trade]||"wrench",13)} ${esc(r.trade)} · need ${r.need}</small></div><div class="cb-fill"><span class="cb-meter" style="--f:${r.filled.length/r.need*100}%;--i:${Math.min(r.need,r.filled.length+inv.length)/r.need*100}%"></span><b class="cb-status">${r.filled.length} / ${r.need} filled</b>${inv.length?`<small>${inv.length} invited, awaiting reply</small>`:open?`<small>${open} open</small>`:`<small class="ok">${I("check",12)} Slot full</small>`}</div></header>
  <ul class="cb-crew">${r.filled.map(c=>`<li class="on">${avatar(U(c),"sm")}<span>${esc(nameOf(U(c)))}</span><i>${(r.invites||[]).some(i=>i.cid===c&&i.status==="booked")?"Booked":"On crew"}</i></li>`).join("")}${inv.map(i=>`<li class="inv">${avatar(U(i.cid),"sm")}<span>${esc(nameOf(U(i.cid)))}</span><i>Invited ${ago(i.date)}</i></li>`).join("")}</ul>
  ${open?(sg.avail.length?`<ul class="cb-sug">${sg.avail.slice(0,4).map((x,k)=>`<li><label><input type="checkbox" data-pick="${r.id}:${x.u.id}" ${k<want?"checked":""}>${avatar(x.u,"sm")}<span class="cb-who"><b>${esc(x.u.biz)}</b><small>${esc(townOf(x.u.zip))} · ${x.d} mi · ${x.r.n?"★ "+x.r.avg.toFixed(1):"New"} · ${verifiedJobs(x.u.id)} verified jobs</small></span>${rapidChip(x.u.id)}<span class="cb-av">${I("check",12)} Free ${esc(win)}</span></label></li>`).join("")}</ul>`:`<p class="muted small cb-none">No available ${esc(r.trade.toLowerCase())} pros within range for these dates yet. Open slots stay listed on the project board.</p>`)+(sg.busy.length?`<p class="small muted cb-busy">${I("clock",12)} ${sg.busy.length} matching pro${sg.busy.length>1?"s are":" is"} busy in this window and hidden.</p>`:""):""}</article>`}).join("")}
 ${s.open>0?`<div class="cb-bar"><span class="muted small" id="cbCount"></span><button class="btn" id="cbInvite">${I("send",16)}Invite selected</button><button class="btn primary" id="cbBook">${I("check",16)}Book whole crew</button></div>`:`<div class="callout">${I("check",20)}<div><b>Crew complete</b><div class="muted">Every slot is filled for ${esc(win)}.</div></div></div>`}</div>`}
function inviteCallout(p,m){if(!m||m.role!=="contractor")return"";const mine=p.roles.map(r=>({r,i:(r.invites||[]).find(i=>i.cid===m.id&&i.status==="invited")})).filter(x=>x.i);
 return mine.map(({r,i})=>`<div class="callout invite" data-invite="${r.id}">${I("bell",20)}<div><b>You're invited: ${esc(r.label)}</b><div class="muted">${fmtD(p.start)} – ${fmtD(p.end)} · ${esc(townOf(p.zip))} · invited ${ago(i.date)}</div></div><div class="actions"><button class="btn primary sm" data-inv-acc="${r.id}">Accept</button><button class="btn sm ghost" data-inv-dec="${r.id}">Decline</button></div></div>`).join("")}
