function v2dash(m){if(m.role==="customer"){const js=DB.jobs.filter(j=>j.cust===m.id&&!j.archived);const bids=js.filter(j=>j.status==="posted"&&DB.quotes.filter(q=>q.job===j.id&&q.price!=null).length>=2);const esc_=js.filter(j=>j.escrow);const ests=(DB.estimates||[]).filter(e=>e.uid===m.id);
  return`<div class="v2strip">${bids.map(j=>`<a class="v2tile t-cmp" href="${href("compare",j.id)}">${I("layers",18)}<b>Compare ${DB.quotes.filter(q=>q.job===j.id&&q.price!=null).length} bids</b><small>${esc(j.title)}</small></a>`).join("")}${esc_.map(j=>{const n=j.escrow.ms.filter(x=>x.status==="requested").length;return`<a class="v2tile t-esc" href="${href("job",j.id)}#escrow">${I("lock",18)}<b>${n?n+" sign-off waiting":"Escrow (test)"}</b><small>${esc(j.title)}</small></a>`}).join("")}<a class="v2tile t-est" href="${href("estimate")}">${I("camera",18)}<b>Photo-to-quote</b><small>${ests.length?ests.length+" saved estimate"+(ests.length>1?"s":""):"Ballpark any job in 30 sec"}</small></a></div>`}
 if(m.role==="contractor"){const inv=(DB.projects||[]).flatMap(p=>p.roles.filter(r=>(r.invites||[]).some(i=>i.cid===m.id&&i.status==="invited")).map(r=>({p,r})));const rs=respStats(m.id);
  return`<div class="v2strip"><div class="v2tile t-rap ${isRapid(m.id)?"hot":""}">${I("zap",18)}<b>${rs.n?mins(rs.med):"—"} median reply</b><small>${isRapid(m.id)?"Rapid responder badge earned":"Reply in under 1 hour to earn Rapid responder"}</small></div>${inv.map(({p,r})=>`<a class="v2tile t-inv" href="${href("project",p.id)}">${I("bell",18)}<b>Crew invite</b><small>${esc(r.label)} · ${esc(p.title)}</small></a>`).join("")}<a class="v2tile" href="${href("pro",m.id)}">${I("camera",18)}<b>${verifiedPhotos(m.id).length} verified photos</b><small>Your photo-verified portfolio</small></a></div>`}
 if(m.role==="pm"){const ps=(DB.projects||[]).filter(p=>p.pm===m.id&&p.status!=="completed");return`<div class="v2strip">${ps.map(p=>{const s=slots(p);return`<a class="v2tile t-cb" href="${href("project",p.id,{tab:"builder"})}">${I("users",18)}<b>${s.f}/${s.n} crew filled</b><small>${esc(p.title)}</small></a>`}).join("")}</div>`}return""}
